  "sources": ["angular:styles/component:css;c8dbd71d56a2b32c7d3c833bb1c2392cdd9a1effac81d98558ab25d44dcbb027;C:\Users\mchauhan\Desktop\Perfect Circle 2.0\Perfect_Circle_2o\pchub-prod/frontend/src/app/features/srp/srp-form.component.ts"],
  "sourcesContent": ["\n    :host { display:block; font-family:inherit; }\n    .srp-shell { display:flex; flex-direction:column; height:100%; background:#f0f2f7; }\n    .srp-toolbar { display:flex; align-items:center; gap:8px; padding:8px 16px; background:#fff; border-bottom:1px solid #dde2ee; flex-shrink:0; }\n    .srp-toolbar::before { content:''; position:absolute; left:0; right:0; top:0; height:2px; background:linear-gradient(90deg,#00aeef,#f5a800); }\n    .srp-body { display:flex; flex:1; overflow:hidden; gap:0; }\n    /* Stepper nav */\n    .srp-stepper { width:200px; flex-shrink:0; background:#fff; border-right:1px solid #dde2ee; overflow-y:auto; padding:8px 0; }\n    .step-item { display:flex; align-items:center; gap:8px; padding:8px 14px; cursor:pointer; font-size:12px; color:#5a6b8a; transition:all .12s; border-left:3px solid transparent; }\n    .step-item:hover { background:#f5f7fb; color:#1a2240; }\n    .step-item.active { background:rgba(37,99,235,.07); color:#2563eb; font-weight:700; border-left-color:#2563eb; }\n    .step-item.complete .step-num { background:#16a34a; color:#fff; }\n    .step-num { width:20px; height:20px; border-radius:50%; background:#e2e8f0; color:#64748b; font-size:10px; font-weight:700; display:inline-flex; align-items:center; justify-content:center; flex-shrink:0; }\n    /* Content */\n    .srp-content { flex:1; overflow-y:auto; padding:20px; }\n    .srp-section { background:#fff; border:1px solid #dde2ee; border-radius:8px; margin-bottom:14px; overflow:hidden; }\n    .srp-sec-hdr { display:flex; align-items:center; gap:8px; padding:11px 16px; background:#f8fafc; border-bottom:1px solid #e2e8f0; cursor:pointer; user-select:none; }\n    .srp-sec-hdr h3 { font-size:12.5px; font-weight:700; color:#1a2240; margin:0; flex:1; }\n    .srp-sec-body { padding:16px; }\n    .srp-grid { display:grid; grid-template-columns:1fr 1fr; gap:12px; }\n    .srp-grid-3 { display:grid; grid-template-columns:1fr 1fr 1fr; gap:12px; }\n    .srp-full { grid-column:1/-1; }\n    .srp-field { display:flex; flex-direction:column; gap:4px; }\n    .srp-label { font-size:11px; font-weight:600; color:#5a6b8a; text-transform:uppercase; letter-spacing:.3px; }\n    .srp-required::after { content:' *'; color:#dc2626; }\n    .srp-input { border:1px solid #dde2ee; border-radius:6px; padding:7px 10px; font-size:12.5px; font-family:inherit; background:#fff; outline:none; transition:border-color .12s; }\n    .srp-input:focus { border-color:#2563eb; box-shadow:0 0 0 3px rgba(37,99,235,.1); }\n    .srp-textarea { border:1px solid #dde2ee; border-radius:6px; padding:8px 10px; font-size:12.5px; font-family:inherit; background:#fff; outline:none; resize:vertical; min-height:80px; line-height:1.5; }\n    .srp-textarea:focus { border-color:#2563eb; box-shadow:0 0 0 3px rgba(37,99,235,.1); }\n    .srp-select { border:1px solid #dde2ee; border-radius:6px; padding:7px 10px; font-size:12.5px; font-family:inherit; background:#fff; cursor:pointer; outline:none; }\n    .srp-select:focus { border-color:#2563eb; }\n    /* Yes/No toggle */\n    .yn-wrap { display:flex; gap:0; border:1px solid #dde2ee; border-radius:6px; overflow:hidden; }\n    .yn-btn { flex:1; padding:6px 12px; font-size:12px; font-weight:600; cursor:pointer; border:none; background:#fff; color:#64748b; transition:all .12s; font-family:inherit; }\n    .yn-btn.yn-active-yes { background:#dcfce7; color:#166534; }\n    .yn-btn.yn-active-no  { background:#fee2e2; color:#991b1b; }\n    /* Status badge */\n    .status-banner { display:flex; align-items:center; gap:10px; padding:10px 14px; border-radius:7px; margin-bottom:14px; font-size:12.5px; }\n    .status-banner.draft    { background:#eff6ff; border:1px solid #bfdbfe; color:#1d4ed8; }\n    .status-banner.approval { background:#fefce8; border:1px solid #fde68a; color:#92400e; }\n    .status-banner.approved { background:#f0fdf4; border:1px solid #bbf7d0; color:#15803d; }\n    .status-banner.rejected { background:#fef2f2; border:1px solid #fecaca; color:#b91c1c; }\n    /* TOMS table */\n    .toms-table { width:100%; border-collapse:collapse; font-size:12px; }\n    .toms-table th { background:#f5f7fb; padding:7px 8px; font-size:10.5px; font-weight:700; text-transform:uppercase; letter-spacing:.3px; color:#5a6b8a; border-bottom:2px solid #e2e8f0; text-align:left; }\n    .toms-table td { padding:6px 8px; border-bottom:1px solid #f0f2f7; vertical-align:middle; }\n    .toms-table .toms-input { border:1px solid #dde2ee; border-radius:4px; padding:4px 6px; font-size:12px; font-family:inherit; background:#fff; outline:none; width:100%; }\n    .toms-table .toms-input:focus { border-color:#2563eb; }\n    /* Delivery table */\n    .del-table { width:100%; border-collapse:collapse; font-size:12.5px; }\n    .del-table th { background:#f5f7fb; padding:7px 10px; font-size:10.5px; font-weight:700; text-transform:uppercase; color:#5a6b8a; border-bottom:2px solid #e2e8f0; }\n    .del-table td { padding:6px 8px; border-bottom:1px solid #f0f2f7; }\n    /* Buttons */\n    .btn { display:inline-flex; align-items:center; gap:5px; padding:7px 16px; border-radius:7px; border:1px solid transparent; cursor:pointer; font-size:12.5px; font-weight:600; font-family:inherit; transition:all .12s; }\n    .btn-primary { background:#2563eb; color:#fff; border-color:#2563eb; }\n    .btn-primary:hover { background:#1d4ed8; }\n    .btn-success { background:#16a34a; color:#fff; border-color:#16a34a; }\n    .btn-success:hover { background:#15803d; }\n    .btn-danger  { background:#dc2626; color:#fff; border-color:#dc2626; }\n    .btn-ghost   { background:#fff; color:#5a6b8a; border-color:#dde2ee; }\n    .btn-ghost:hover { background:#f5f7fb; }\n    .btn-sm { padding:5px 12px; font-size:12px; }\n    .save-indicator { font-size:11px; color:#16a34a; opacity:0; transition:opacity .3s; }\n    .save-indicator.show { opacity:1; }\n    .chip { display:inline-block; padding:2px 8px; border-radius:10px; background:rgba(37,99,235,.08); color:#1d4ed8; font-size:10.5px; font-weight:600; }\n    .badge { display:inline-block; padding:3px 10px; border-radius:10px; font-size:11px; font-weight:700; }\n    .badge-blue { background:#dbeafe; color:#1d4ed8; }\n    .badge-amber { background:#fef3c7; color:#92400e; }\n    .badge-green { background:#dcfce7; color:#166534; }\n    .badge-red { background:#fee2e2; color:#991b1b; }\n    .text-muted { color:#64748b; font-size:12px; }\n    /* Progress bar */\n    .srp-progress { display:flex; gap:4px; margin-bottom:12px; }\n    .srp-progress-seg { flex:1; height:4px; border-radius:2px; background:#e2e8f0; transition:background .3s; }\n    .srp-progress-seg.filled { background:#2563eb; }\n  "],
